import{d as u,C as i,o as g,c,j as a,a as l,E as n,a3 as t}from"./chunks/framework.Q4yG9rk_.js";const q=JSON.parse('{"title":"杂卦传","description":"以对举方式点明各卦要义之传——用极简的卦德互照六十四卦，建立从序卦到逐卦阅读的复习入口。","frontmatter":{"title":"杂卦传","description":"以对举方式点明各卦要义之传——用极简的卦德互照六十四卦，建立从序卦到逐卦阅读的复习入口。","category":"guide","aliases":["杂卦传","杂卦","za gua zhuan"],"source":["《周易·杂卦传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/za-gua-zhuan.md","filePath":"yijing/shi-yi/za-gua-zhuan.md","lastUpdated":1790587309000}'),m={name:"yijing/shi-yi/za-gua-zhuan.md"},x=u({...m,setup(p){const o=[{id:"duan-01",label:"一、乾刚坤柔",showLabel:!0,sentences:[["《乾》刚，《坤》柔；《比》乐，《师》忧；《临》《观》之义，",{text:"或与或求",glossary:"g04"},"。"]],note:["乾卦的性质是刚健，坤卦是柔顺；比卦亲比相辅，所以和乐，师卦兴师众动，所以堪忧；临、观两卦的旨趣，一个重在给予，一个重在求取。"]},{id:"duan-02",label:"二、屯蒙震艮",showLabel:!0,sentences:[["《屯》见而",{text:"不失其居",glossary:"g05"},"，《蒙》杂而著；《震》，起也，《艮》，止也。"]],note:["屯卦讲初生之难：事物显现了，却不失自己的居处；蒙卦讲蒙昧混杂，但会渐渐显出条理。震是发动，艮是停止。"]},{id:"duan-03",label:"三、损益大畜无妄",showLabel:!0,sentences:[["《损》《益》，盛衰之始也；《大畜》，时也；《无妄》，灾也。"]],note:["损、益两卦，是盛与衰开始显现的地方；大畜讲的是等待时机；无妄讲的却是——本来无妄，也会遇上灾。"]},{id:"duan-04",label:"四、萃升谦豫",showLabel:!0,sentences:[["《萃》聚而《升》不来也，《谦》轻而《豫》怠也；《噬嗑》，食也，《贲》，无色也。"]],note:["萃是聚集；升是上升，越升越远，回不来了。谦是把自己看轻；豫是安逸过头而生懈怠。噬嗑讲进食；贲讲无色——文饰到了极点，反而归于朴素。"]},{id:"duan-05",label:"五、兑巽随蛊剥复",showLabel:!0,sentences:[["《兑》见而《巽》伏也，《随》无故也，《蛊》则",{text:"饬",glossary:"g06"},"也；《剥》，烂也，《复》，反也。"]],note:["兑显现于外，巽伏藏于内。随是无所作为而自然相从；蛊则是顺从积久成了弊病，必须整治。剥是朽烂剥落，复是返回根本。"]},{id:"duan-06",label:"六、晋明夷井困咸",showLabel:!0,sentences:[["《晋》，昼也；《明夷》，诛也；《井》通而《困》相遇也；《咸》速也。"]],note:["晋是白昼，明夷是光明受伤；井是通畅，困则是受阻而相遇；咸是感应的迅速。"]},{id:"duan-07",label:"七、恒涣节解蹇",showLabel:!0,sentences:[["《恒》，久也；《涣》，离也；《节》，止也；《解》，缓也；《蹇》，难也。"]],note:["恒是长久，涣是离散，节是节制，解是舒缓，蹇是艰难。"]},{id:"duan-08",label:"八、睽家人否泰",showLabel:!0,sentences:[["《睽》，外也；《家人》，内也；《否》《泰》，",{text:"反其类",glossary:"g07"},"也；《大壮》则止，《遁》则退也。"]],note:["睽主于外（乖离），家人主于内（亲近）；否与泰性质相反，却可以彼此转化。大壮知道要止，遁知道要退。"]},{id:"duan-09",label:"九、大有同人革鼎",showLabel:!0,sentences:[["《大有》，众也；《同人》，亲也；《革》，去故也；《鼎》，",{text:"取新",glossary:"g08"},"也；《小过》，过也；《",{text:"中孚",glossary:"g09"},"》，信也。"]],note:["大有是拥有众多，同人是彼此亲附；革是除去旧故，鼎是建立新器；小过是稍有逾越，中孚是内心诚信。"]},{id:"duan-10",label:"十、丰旅离坎",showLabel:!0,sentences:[["《丰》，多故也；亲寡《旅》也。《离》上而《坎》下也；《小畜》，寡也；《履》，不处也；《需》，不进也。"]],note:["丰是事端繁多，旅是亲族寡少。离在上、坎在下；小畜所蓄无多，履是不肯安处，需是等待不进。"]},{id:"duan-11",label:"十一、讼大过姤渐",showLabel:!0,sentences:[["《讼》，不亲也；《大过》，颠也；《姤》，遇也，柔遇刚也；《渐》，女归待男行也。"]],note:["讼是相争而不亲；大过是本末过甚而颠倒；姤是相遇，是柔与刚相遇；渐是女子出嫁，要等男方按礼来行。"]},{id:"duan-12",label:"十二、颐与既未济",showLabel:!0,sentences:[["《颐》，养正也；《",{text:"既济",glossary:"g10"},"》，定也；《归妹》，女之终也；《",{text:"未济",glossary:"g11"},"》，男之穷也。"]],note:["颐是养之以正；既济是已经安定；归妹是女子有了归宿；未济是男子尚未通达。"]},{id:"duan-13",label:"十三、夬刚决柔",showLabel:!0,sentences:[["《夬》，决也，刚决柔也。君子道长，小人道忧也。"]],note:["夬是决断，五刚决去一柔。君子之道在生长，小人之道在忧惧。"]}],r=[{id:"g01",term:"杂卦",pinyin:"zá guà",meaning:"错杂、错综地排列卦义，以对举和互照的方式提示各卦之要。杂不是杂乱，而是换一种关系视角。"},{id:"g02",term:"卦德",pinyin:"guà dé",meaning:"一卦所呈现的主要性质、功能或倾向。「刚」「柔」「起」「止」「信」等都是高度压缩的卦德提示。"},{id:"g03",term:"对举",pinyin:"duì jǔ",meaning:"把相反或相成的两种状态放在一起说明。对举不是简单二选一，而是让一方照见另一方的边界。"},{id:"g04",term:"或与或求",pinyin:"yǔ qiú",meaning:"临有与、给予、接近的一面，观有求、观察、仰观的一面，写出关系中给予与学习的两种姿态。"},{id:"g05",term:"不失其居",pinyin:"bù shī qí jū",meaning:"在屯难、萌动与显现中不失去自己的根基和位置。初始阶段不宜只求扩张，更要先稳住居处。"},{id:"g06",term:"饬",pinyin:"chì",meaning:"整饬、修治。「蛊则饬」说明积弊显现后不能只维持表面和气，而要认真整理和修复。"},{id:"g07",term:"反其类",pinyin:"fǎn qí lèi",meaning:"否与泰性质相反，却可以彼此转化；通塞、盛衰都不是永恒停留的类别。"},{id:"g08",term:"取新",pinyin:"qǔ xīn",meaning:"鼎所代表的建立新器、承载新秩序。革去旧故之后，还需要有新的制度、能力和方法接续。"},{id:"g09",term:"中孚",pinyin:"zhōng fú",meaning:"内在诚信、中心真实。「信」不只在宏大承诺，也体现在小处的谨慎与持续兑现。"},{id:"g10",term:"既济",pinyin:"jì jì",meaning:"已经渡过、事情暂时完成。「定」是阶段性安定，并不意味着变化从此停止。"},{id:"g11",term:"未济",pinyin:"wèi jì",meaning:"尚未渡过、尚未完成。「穷」指当前阶段未能抵达，并保留继续变化、继续行动的可能。"}];return(b,e)=>{const s=i("DaoReadingPrelude"),d=i("DaoTextReading"),h=i("DaoKeywordCards");return g(),c("div",null,[e[0]||(e[0]=a("h1",{id:"杂卦传",tabindex:"-1"},[l("杂卦传 "),a("a",{class:"header-anchor",href:"#杂卦传","aria-label":'Permalink to "杂卦传"'},"​")],-1)),n(s,{title:"把六十四卦放在对照中读",summary:"《杂卦传》篇幅极短，却把六十四卦放进一面关系之镜：乾刚坤柔，比乐师忧，震起艮止，损益见盛衰，既济定而未济穷。它不沿着序卦讲一条路，而是用对举和极简卦德，让每一卦最突出的气质彼此照见。",points:[{label:"先读字",text:"先看每一卦被压缩成的一个字，感受《杂卦》的凝练。"},{label:"再看对",text:"把刚柔、乐忧、聚升、内外、损益等放在一起，看差异如何显义。"},{label:"后回卦",text:"最后回到具体卦页，用这一个字作入口，不把它当成一卦全部的定义。"}],hint:"《序卦》像一条路，说明卦为何相承；《杂卦》像一面镜，照出卦最鲜明的一面。两篇合读，六十四卦才既有次序，也有层次。"}),e[1]||(e[1]=t("",13)),n(d,{colophon:"刚柔对举 · 卦德互照 · 一字定调 · 既济未济",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"杂卦传原文",sections:o,glossary:r}),e[2]||(e[2]=a("blockquote",null,[a("p",null,"注：本页采用你提供的通行本文字整理。不同底本在「诛／伤」「萃聚而升不来也」等字词、句读和解释上可能有异文；其中「女之终」「男之穷」带有古代阴阳与婚姻秩序的语境，现代阅读时应区分其结构象征与现实规范。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:[{term:"杂卦",pinyin:["zá","guà"],meaning:"错杂、错综地排列卦义，以对举和互照的方式提示各卦之要。杂不是杂乱，而是换一种关系视角。"},{term:"卦德",pinyin:["guà","dé"],meaning:"一卦所呈现的主要性质、功能或倾向。「刚」「柔」「起」「止」「信」等都是高度压缩的卦德提示。"},{term:"对举",pinyin:["duì","jǔ"],meaning:"把相反或相成的两种状态放在一起说明。对举不是简单二选一，而是让一方照见另一方的边界。"},{term:"或与或求",pinyin:["yǔ","qiú"],meaning:"临有与、给予、接近的一面，观有求、观察、仰观的一面，写出关系中给予与学习的两种姿态。"},{term:"不失其居",pinyin:["bù","shī","qí","jū"],meaning:"在屯难、萌动与显现中不失去自己的根基和位置。初始阶段不宜只求扩张，更要先稳住居处。"},{term:"饬",pinyin:["chì"],meaning:"整饬、修治。「蛊则饬」说明积弊显现后不能只维持表面和气，而要认真整理和修复。"},{term:"反其类",pinyin:["fǎn","qí","lèi"],meaning:"否与泰性质相反，却可以彼此转化；通塞、盛衰都不是永恒停留的类别。"},{term:"取新",pinyin:["qǔ","xīn"],meaning:"鼎所代表的建立新器、承载新秩序。革去旧故之后，还需要有新的制度、能力和方法接续。"},{term:"中孚",pinyin:["zhōng","fú"],meaning:"内在诚信、中心真实。「信」不只在宏大承诺，也体现在小处的谨慎与持续兑现。"},{term:"既济",pinyin:["jì","jì"],meaning:"已经渡过、事情暂时完成。「定」是阶段性安定，并不意味着变化从此停止。"},{term:"未济",pinyin:["wèi","jì"],meaning:"尚未渡过、尚未完成。「穷」指当前阶段未能抵达，并保留继续变化、继续行动的可能。"}]}),e[4]||(e[4]=t("",22))])}}});export{q as __pageData,x as default};
